// UpdateReminderRequest The whole rule: `PUT` replaces every field, so the rule fields are
// required. Recurrence additions are optional with the same defaults as a
// create: `interval` 1, `end_kind` `none` and `start_date` today in
// `timezone`. Editing the rule resets the fired counter.
type UpdateReminderRequest struct {
	// Enabled `false` cancels the pending occurrence and clears `next_due_at`.
	//
	//
	// Example: true
	Enabled bool `json:"enabled"`

	// EndCount Total number of occurrences for `count`.
	EndCount *int `json:"end_count,omitempty"`

	// EndDate Last allowed day for `until`.
	EndDate *openapi_types.Date `json:"end_date,omitempty"`

	// EndKind Stop condition: never, until `end_date`, or after `end_count`.
	//
	// Example: none
	EndKind *UpdateReminderRequestEndKind `json:"end_kind,omitempty"`

	// Interval Every N days/weeks/months/years, relative to `start_date`.
	//
	// Example: 1
	Interval *int `json:"interval,omitempty"`

	// Message Reminder text, 1..1500 characters.
	//
	// Example: Выпить таблетку
	Message string `json:"message"`

	// MonthWeekPosition For a monthly nth-weekday rule: 1..4 or -1 for the last weekday.
	MonthWeekPosition *int `json:"month_week_position,omitempty"`

	// MonthWeekday ISO weekday (1 = Monday, 7 = Sunday) of an nth-weekday monthly rule.
	MonthWeekday *int `json:"month_weekday,omitempty"`

	// RecipientIds Members of the space who get the message; the recipients stay when omitted.
	//
	// Example: ["11111111-1111-4111-8111-111111111111"]
	RecipientIds *[]string `json:"recipient_ids,omitempty"`

	// RepeatMinutes Repeat interval of an unconfirmed occurrence.
	//
	// Example: 15
	RepeatMinutes int `json:"repeat_minutes"`

	// ScheduleDays Days of a `weekly` or `monthly` day-of-month rule. Weekly days are
	// 1..7, monthly days are 1..31. Empty for `once`, `daily`, `yearly` and
	// an nth-weekday `monthly` rule.
	//
	//
	// Example: [2,4]
	ScheduleDays *[]int `json:"schedule_days,omitempty"`

	// ScheduleKind Shape of the recurrence.
	//
	// * `once` — a single occurrence on `start_date` at `time`; the reminder
	//   is finished after the occurrence is confirmed.
	// * `daily` — every `interval` days (1 means every day) at `time`.
	// * `weekly` — every `interval` weeks on `schedule_days`, ISO weekdays 1..7
	//   (1 = Monday, 7 = Sunday).
	// * `monthly` — every `interval` months, either on `schedule_days` (days of
	//   month 1..31, a day the month does not have means its last day) or on
	//   the nth weekday given by `month_week_position` and `month_weekday`.
	// * `yearly` — every `interval` years on the month and day of `start_date`;
	//   29 February becomes 28 February in a non-leap year.
	//
	//
	// Example: weekly
	ScheduleKind ScheduleKind `json:"schedule_kind"`

	// SpaceId Reminders space of the rule; the reminder stays where it is when omitted.
	//
	// Example: 44444444-4444-4444-8444-444444444444
	SpaceId *string `json:"space_id,omitempty"`

	// StartDate First possible day as `YYYY-MM-DD` in `timezone`. Omitted means today
	// in `timezone`.
	//
	//
	// Example: 2026-01-05
	StartDate *openapi_types.Date `json:"start_date,omitempty"`

	// Time Local wall clock time as `HH:MM`.
	//
	// Example: 20:00
	Time string `json:"time"`

	// Timezone IANA time zone of the schedule.
	//
	// Example: Europe/Moscow
	Timezone string `json:"timezone"`
}

// UpdateReminderRequestEndKind Stop condition: never, until `end_date`, or after `end_count`.
//
// Example: none
type UpdateReminderRequestEndKind string

// UseProjectMaterialRequest Quantity of a planned material to withdraw from the stock.
type UseProjectMaterialRequest struct {
	// Qty Quantity to withdraw; must be positive. A withdrawal larger than the
	// stock is a conflict.
	//
	//
	// Example: 5
	Qty float64 `json:"qty"`
}

// Wish One entry of the wish list: either a catalogue item or free text,
// together with its shop links. `item` and `stock_qty` are present only
// when the entry points at a catalogue item.
type Wish struct {
	// CatalogItemId Catalogue item the entry points at, or an empty string for free
	// text.
	//
	//
	// Example: 7d2e5c1a-8b3f-4c6d-9e0a-1b2c3d4e5f60
	CatalogItemId string `json:"catalog_item_id"`

	// CreatedAt When the entry was added.
	//
	// Example: 2026-01-15T09:30:00Z
	CreatedAt time.Time `json:"created_at"`

	// CreatedBy Principal id of the member who added the entry.
	//
	// Example: 6f1c0a3e-5b9d-4a1f-9c2b-7e8d0f1a2b3c
	CreatedBy string `json:"created_by"`

	// Id Wish list entry id (UUID).
	//
	// Example: 3f0b9a2c-6d41-4e7b-8c55-1a2b3c4d5e6f
	Id string `json:"id"`

	// Item A catalogue entry: either a global item shared by every workspace or a
	// private item of one workspace. `stock_qty` and `in_inventory` describe
	// what the requested workspace holds.
	Item *CraftItem `json:"item,omitempty"`

	// Links Shop pages where the item can be bought; empty when none.
	Links []WishLink `json:"links"`

	// Note Free-form note, for example for whom it is; empty when none.
	//
	// Example: на подарок
	Note string `json:"note"`

	// Priority How much it is wanted: 0 is normal, 1 is important, 2 is the most
	// important. The list is sorted by it.
	//
	//
	// Example: 2
	Priority int `json:"priority"`

	// QtyWanted Wanted quantity, or `null` while undecided.
	//
	// Example: 3
	QtyWanted *float64 `json:"qty_wanted"`

	// Status State of a wish list entry: `wanted` is still to buy, `ordered` is on its
	// way, `bought` is done.
	//
	//
	// Example: wanted
	Status WishStatus `json:"status"`

	// Title Name of the wanted item.
	//
	// Example: Жемчуг айвори 2 мм
	Title string `json:"title"`

	// UpdatedAt When the entry last changed.
	//
	// Example: 2026-01-16T08:00:00Z
	UpdatedAt time.Time `json:"updated_at"`
}

// WishInput A new wish list entry. Send either `catalog_item_id` or a free text
// `title`; when a catalogue item is named, the title defaults to its name.
type WishInput struct {
	// CatalogItemId Catalogue item to want. It must be visible to the workspace and is
	// accepted only once at a time.
	//
	//
	// Example: 7d2e5c1a-8b3f-4c6d-9e0a-1b2c3d4e5f60
	CatalogItemId *string `json:"catalog_item_id,omitempty"`

	// Note Free-form note.
	//
	// Example: на подарок
	Note *string `json:"note,omitempty"`

	// Priority How much it is wanted: 0, 1 or 2.
	//
	// Example: 2
	Priority *int `json:"priority,omitempty"`

	// QtyWanted Wanted quantity; must be positive when sent.
	//
	// Example: 3
	QtyWanted *float64 `json:"qty_wanted,omitempty"`

	// Title Name of the wanted item, up to 200 characters. Required when there is
	// no catalogue item.
	//
	//
	// Example: Жемчуг айвори 2 мм
	Title *string `json:"title,omitempty"`
}

// WishLink One shop page where a wish can be bought, with the optional price and
// availability reported by the shop.
type WishLink struct {
	// CheckedAt When the availability was checked, or `null`.
	//
	// Example: 2026-01-16T08:00:00Z
	CheckedAt *time.Time `json:"checked_at"`

	// CreatedAt When the link was added.
	//
	// Example: 2026-01-15T09:30:00Z
	CreatedAt time.Time `json:"created_at"`

	// Currency ISO 4217 currency code in upper case; empty when unknown.
	//
	//
	// Example: RUB
	Currency string `json:"currency"`

	// Id Link id (UUID), used to remove the link.
	//
	// Example: 9a8b7c6d-5e4f-4a3b-8c2d-1e0f9a8b7c6d
	Id string `json:"id"`

	// InStock Whether the shop had the item in stock when it was checked, or `null`
	// when unknown.
	//
	//
	// Example: true
	InStock *bool `json:"in_stock"`

	// Price Price of the item as reported, or `null` when unknown.
	//
	// Example: 12.5
	Price *float64 `json:"price"`

	// ShopName Shop name shown as a chip; empty when unknown.
	//
	// Example: Магазин бусин
	ShopName string `json:"shop_name"`

	// Url Absolute `http://` or `https://` address of the shop page.
	//
	// Example: https://shop.example/beads
	Url string `json:"url"`
}

// WishLinkInput A shop page where a wish can be bought.
type WishLinkInput struct {
	// Currency ISO 4217 currency code; it is stored in upper case. Empty when
	// unknown.
	//
	//
	// Example: RUB
	Currency *string `json:"currency,omitempty"`

	// InStock Whether the shop has the item in stock.
	//
	// Example: true
	InStock *bool `json:"in_stock,omitempty"`

	// Price Price of the item; must not be negative.
	//
	// Example: 12.5
	Price *float64 `json:"price,omitempty"`

	// ShopName Shop name shown as a chip; defaults to the host name.
	//
	// Example: Магазин бусин
	ShopName *string `json:"shop_name,omitempty"`

	// Url Absolute `http://` or `https://` address of the shop page.
	//
	// Example: https://shop.example/beads
	Url string `json:"url"`
}

// WishStatus State of a wish list entry: `wanted` is still to buy, `ordered` is on its
// way, `bought` is done.
//
// Example: wanted
type WishStatus string

// WishUpdateRequest The editable fields of a wish list entry. Quantity, priority and note are
// replaced; an omitted status keeps the current one.
type WishUpdateRequest struct {
	// Note Free-form note; an empty string clears it.
	//
	// Example:
	Note string `json:"note"`

	// Priority How much it is wanted: 0, 1 or 2.
	//
	// Example: 1
	Priority int `json:"priority"`

	// QtyWanted New wanted quantity; must be positive when sent. `null` clears it.
	//
	//
	// Example: 5
	QtyWanted *float64 `json:"qty_wanted,omitempty"`

	// Status State of a wish list entry: `wanted` is still to buy, `ordered` is on its
	// way, `bought` is done.
	//
	//
	// Example: wanted
	Status *WishStatus `json:"status,omitempty"`
}

// Workspace A shared workspace. Every member has the same rights; data of a
// workspace is visible to its members only.
type Workspace struct {
	// App Mini-app a space belongs to. Sharing a space shares the data of that
	// mini-app only.
	//
	//
	// Example: warehouse
	App SpaceApp `json:"app"`

	// CreatedAt When the workspace was created.
	//
	// Example: 2026-01-15T09:30:00Z
	CreatedAt time.Time `json:"created_at"`

	// Id Workspace id (UUID), used in every workspace-scoped path.
	//
	// Example: 44444444-4444-4444-8444-444444444444
	Id string `json:"id"`

	// Name Name every member sees.
	//
	// Example: Дом
	Name string `json:"name"`

	// Personal Whether this is the creator's own default space of the mini-app.
	//
	// Example: true
	Personal bool `json:"personal"`
}

// WorkspaceCandidate A user who has signed in at least once and is not a member of the
// workspace yet.
type WorkspaceCandidate struct {
	// AvatarUrl Gravatar image of the e-mail, with an identicon fallback.
	//
	// Example: https://www.gravatar.com/avatar/abc?s=96&d=identicon
	AvatarUrl string `json:"avatar_url"`

	// DisplayName Display name from the SSO provider; empty when unknown.
	//
	// Example: Иван Петров
	DisplayName string `json:"display_name"`

	// Email E-mail from the SSO provider; empty when unknown.
	//
	// Example: user@example.com
	Email string `json:"email"`

	// UserId Principal id of the user to add.
	//
	// Example: 6f1c0a3e-5b9d-4a1f-9c2b-7e8d0f1a2b3c
	UserId string `json:"user_id"`
}

// WorkspaceMember A member of a workspace together with the information the member list
// shows.
type WorkspaceMember struct {
	// AvatarUrl Gravatar image of the e-mail; addresses without a Gravatar fall back
	// to a generated identicon.
	//
	//
	// Example: https://www.gravatar.com/avatar/abc?s=96&d=identicon
	AvatarUrl string `json:"avatar_url"`

	// DisplayName Display name from the SSO provider; empty when unknown.
	//
	// Example: Иван Петров
	DisplayName string `json:"display_name"`

	// Email E-mail from the SSO provider; empty when unknown.
	//
	// Example: user@example.com
	Email string `json:"email"`

	// JoinedAt When the user joined the workspace.
	//
	// Example: 2026-01-15T09:30:00Z
	JoinedAt time.Time `json:"joined_at"`

	// UserId Principal id of the member, the same value as `Me.id`.
	//
	// Example: 6f1c0a3e-5b9d-4a1f-9c2b-7e8d0f1a2b3c
	UserId string `json:"user_id"`
}

